// app/Http/Middleware/EnsureTenant.php
class EnsureTenant
{
    public function handle(Request $request, Closure $next): Response
    {
        $key = $request->header('X-Tenant') ?? $request->route('tenant');
        $tenant = Cache::remember("tenant:$key", 300, fn () => Tenant::where('key', $key)->first());
        abort_unless($tenant, 404);                                  // unknown tenant looks like 'nothing here'
        app()->instance(CurrentTenant::class, new CurrentTenant($tenant));   // scoped for this request
        $response = $next($request);
        return $response->header('X-Tenant-Id', $tenant->id);       // on the way out
    }
}

// app/Http/Middleware/RequestId.php
class RequestId
{
    public function handle(Request $request, Closure $next): Response
    {
        $id = $request->header('X-Request-Id') ?? (string) Str::uuid();
        Log::withContext(['request_id' => $id]);
        return $next($request)->header('X-Request-Id', $id);
    }
    public function terminate(Request $request, Response $response): void
    {
        if (($ms = (microtime(true) - LARAVEL_START) * 1000) > 500) Log::warning('slow request', ['ms' => $ms, 'path' => $request->path()]);
    }
}

