// tests/Feature/TenantMiddlewareTest.php
public function test_unknown_tenant_is_404(): void {
    $this->getJson('/api/v1/orders', ['X-Tenant' => 'nope'])->assertNotFound();
}
public function test_valid_tenant_sets_headers(): void {
    $t = Tenant::factory()->create(['key' => 'acme']);
    Sanctum::actingAs(User::factory()->create());
    $res = $this->getJson('/api/v1/orders', ['X-Tenant' => 'acme']);
    $res->assertOk()->assertHeader('X-Tenant-Id', (string) $t->id)->assertHeader('X-Request-Id');
}
public function test_request_id_is_logged(): void {
    Log::spy();
    $this->getJson('/api/v1/health', ['X-Request-Id' => 'abc-123']);
    Log::shouldHaveReceived('withContext')->with(['request_id' => 'abc-123']);
}
