public function test_sixth_attempt_from_same_ip_is_throttled(): void {
    foreach (range(1, 5) as $i) $this->postJson('/login', ['email' => "u$i@x.com", 'password' => 'bad']);
    $this->postJson('/login', ['email' => 'u6@x.com', 'password' => 'bad'])
         ->assertStatus(429)->assertHeader('Retry-After');
    $this->withServerVariables(['REMOTE_ADDR' => '10.0.0.9'])
         ->postJson('/login', ['email' => 'u7@x.com', 'password' => 'bad'])->assertStatus(422);   // not throttled
}
